// A pre-approved business action for agents: validate, then create a ticket. Agents never get raw API access.
const q = typeof query === 'string' ? JSON.parse(query) : query;
const title = String(q.title || '').trim();
const priority = ['low', 'medium', 'high'].includes(q.priority) ? q.priority : 'medium';
if (title.length < 8) return 'Refused: the title must be at least 8 characters.';
if (/password|api[_-]?key|secret/i.test(String(q.details || ''))) return 'Refused: never put credentials in a ticket.';
const id = 'TCK-' + Date.now().toString().slice(-6);
return JSON.stringify({ id, title, priority, status: 'open' });
